      const proxy = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.6, 0.85, 12), new THREE.MeshBasicMaterial({ visible: false }));
      proxy.position.y = 0.35;
      proxy.userData = { kind: "bowl", index: i };
