      new THREE.Vector2(0.43, 1.45),
      new THREE.Vector2(0.36, 1.7),
      new THREE.Vector2(0.2, 1.86),
      new THREE.Vector2(0.09, 1.95),
      new THREE.Vector2(0.07, 2.15),
      new THREE.Vector2(0, 2.2)
